previewCss:
.darma-loader-darma-b16-orbital-docking { --accent: var(--loader-color, #4f46e5); --accent-2: var(--loader-secondary-color, #a5f3fc); width: var(--loader-size, 122px); height: var(--loader-size, 122px); position: relative; }
.darma-loader-darma-b16-orbital-docking .darma-loader-darma-b16-orbital-docking__rig { position: absolute; inset: 0; animation: darma-loader-darma-b16-orbital-docking-dock-spin calc(var(--loader-speed, 1s) * 6) linear infinite; }
.darma-loader-darma-b16-orbital-docking .darma-loader-darma-b16-orbital-docking__station { position: absolute; left: 8%; top: 42%; width: 40%; height: 16%; border-radius: 5px; background: linear-gradient(var(--accent-2), var(--accent)); }
.darma-loader-darma-b16-orbital-docking .darma-loader-darma-b16-orbital-docking__station::after { content: ''; position: absolute; left: 22%; top: -120%; width: 56%; height: 340%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 55%, transparent); }
.darma-loader-darma-b16-orbital-docking .darma-loader-darma-b16-orbital-docking__craft { position: absolute; right: 8%; top: 42%; width: 30%; height: 16%; border-radius: 5px 40% 40% 5px / 5px 50% 50% 5px; background: linear-gradient(color-mix(in srgb, #fff 25%, var(--accent)), var(--accent)); animation: darma-loader-darma-b16-orbital-docking-dock-approach calc(var(--loader-speed, 1s) * 3.4) cubic-bezier(.5, 0, .3, 1) infinite; }
.darma-loader-darma-b16-orbital-docking .darma-loader-darma-b16-orbital-docking__latch { position: absolute; left: 47%; top: 45%; width: 6%; height: 10%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b16-orbital-docking-dock-latch calc(var(--loader-speed, 1s) * 3.4) ease-out infinite; }
@keyframes darma-loader-darma-b16-orbital-docking-dock-spin { to { transform: rotate(1turn); } }
@keyframes darma-loader-darma-b16-orbital-docking-dock-approach { 0%, 10% { transform: translateX(0); } 56%, 84% { transform: translateX(-46%); } 98%, 100% { transform: translateX(0); } }
@keyframes darma-loader-darma-b16-orbital-docking-dock-latch { 0%, 52% { opacity: 0; transform: scale(.4); } 62%, 84% { opacity: 1; transform: scale(1); box-shadow: 0 0 10px var(--accent-2); } 94%, 100% { opacity: 0; transform: scale(.4); } }

